/* ---------- 行树扁平化（viewport：展开态记忆在各维度名下，跨换轴保留） ---------- */
function flattenRows(dimId) {
  const out = [];
  (function walk(node, path) {
    node.children.forEach((c) => {
      out.push({ node: c, depth: c.depth - 1, path });
      if (state.expanded[dimId].includes(c.id)) walk(c, path + 1);
    });
  })(TREES[dimId], 0);
  return out;
}

