/* 多维棱镜 · 应用核心
 * 状态模型（SDIR state_ownership）：
 *   query     = filters + axes + measure（每次变更加入带归属的轨迹，可回滚）
 *   selection = pinned 锚定集合（跨换轴持久）
 *   viewport  = expanded 展开态 / 滚动（不进轨迹）
 *   mode      = sortDir（顶栏持有，同样入轨迹）
 * 成功标准：换轴动作白名单化 —— 只触碰 rowDim/colDim，其余全部保留。
 */
(function () {
  'use strict';
  const CUBE = window.CUBE;
  const DIMS = CUBE.dims, TREES = CUBE.trees, ROWS = CUBE.rows, MEASURES = CUBE.measures;
  const $ = (sel) => document.querySelector(sel);
  const dimById = Object.fromEntries(DIMS.map((d) => [d.id, d]));
  const measureById = Object.fromEntries(MEASURES.map((m) => [m.id, m]));

  /* ---------- 格式化 ---------- */
  const fmtMoney = (v) => {
    const a = Math.abs(v);
    if (a >= 1e8) return '¥' + (v / 1e8).toFixed(2) + '亿';
    if (a >= 1e4) return '¥' + (v / 1e4).toFixed(1) + '万';
    return '¥' + Math.round(v);
  };
  const fmtInt = (v) => Math.round(v).toLocaleString('zh-CN');
  const fmtPct = (v) => (v * 100).toFixed(1) + '%';
  function fmtMeasure(id, v) {
    const f = measureById[id].fmt;
    return f === 'money' ? fmtMoney(v) : f === 'int' ? fmtInt(v) : fmtPct(v);
  }

  /* ---------- 初始状态 ---------- */
  function initialState() {
    const filters = {}, expanded = {};
    DIMS.forEach((d) => { filters[d.id] = []; expanded[d.id] = []; });
    expanded.category = ['手机通讯']; // 初始示范层级展开（viewport 态）
    return {
      filters,
      rowDim: 'category', colDim: 'quarter',
      measure: 'revenue', sortDir: 'desc',
      pinned: [], expanded
    };
  }
  let state = initialState();

  /* ---------- 状态轨迹（归属 + 回退） ---------- */
  const TRAIL_MAX = 50;
  let trail = [], ptr = -1;
  const clone = (s) => JSON.parse(JSON.stringify(s));
  function pushOp(label, origin) {
    // 轨迹记录：动作 + 来源归属 + 快照。未来分支（回滚后产生新操作）按撤销语义截断。
    // 首条「初始状态」永不移除：重置动作以它为基准。
    trail = trail.slice(0, ptr + 1);
    trail.push({ label, origin, ts: new Date(), snap: clone(state) });
    if (trail.length > TRAIL_MAX) trail.splice(1, 1);
    ptr = trail.length - 1;
  }
  function jumpTo(i) {
    if (i < 0 || i >= trail.length) return;
    ptr = i;
    state = clone(trail[i].snap);
    render({ jumped: true });
  }
  const undo = () => jumpTo(ptr - 1);
  const redo = () => jumpTo(ptr + 1);
  function resetAll() {
    state = clone(trail[0].snap);
    pushOp('重置全部状态', { source: '顶栏', detail: '恢复初始快照' });
    render();
    toast('已重置全部状态（可在轨迹中回退到重置前）');
  }

  /* ---------- 过滤语义：同维度值之间 OR，跨维度 AND ---------- */
  function findNode(dimId, id) {
    let found = null;
    (function walk(n) {
      if (n.id === id) { found = n; return; }
      n.children.forEach(walk);
    })(TREES[dimId]);
    return found;
  }
  function computeFiltered() {
    const allow = {};
    for (const d of DIMS) {
      const checked = state.filters[d.id];
      if (!checked.length) continue;
      const set = new Set();
      checked.forEach((id) => {
        const n = findNode(d.id, id);
        (function collect(x) {
          if (!x.children.length) set.add(x.id);
          x.children.forEach(collect);
        })(n);
      });
      allow[d.id] = set;
    }
    const idxs = [];
    outer: for (let i = 0; i < ROWS.length; i++) {
      const r = ROWS[i];
      for (const d in allow) if (!allow[d].has(r[d])) continue outer;
      idxs.push(i);
    }
    return idxs;
  }
  function aggregate(idxs, measureId) {
    let revenue = 0, profit = 0, orders = 0, returns = 0;
    for (const i of idxs) {
      const r = ROWS[i];
      revenue += r.revenue; profit += r.profit; orders += r.orders; returns += r.returns;
    }
    if (measureId === 'revenue') return revenue;
    if (measureId === 'profit') return profit;
    if (measureId === 'orders') return orders;
    return orders ? returns / orders : NaN; // returnRate
  }

  /* ---------- 行树扁平化（viewport：展开态记忆在各维度名下，跨换轴保留） ----------
   * topOrder 仅对顶层行生效（排序），子孙保持层级自然序，不打散树形分组。 */
  function flattenRows(dimId, topOrder) {
    const out = [];
    (function walk(node, depth) {
      const kids = depth === 0 && topOrder ? topOrder(node.children) : node.children;
      kids.forEach((c) => {
        out.push({ node: c, depth });
        if (state.expanded[dimId].includes(c.id)) walk(c, depth + 1);
      });
    })(TREES[dimId], 0);
    return out;
  }

  /* ---------- 热力梯度（靛蓝单色，11 档；≥7 档白字保 AA 对比） ---------- */
  const RAMP = [];
  for (let i = 0; i <= 10; i++) {
    const t = i / 10;
    const mix = (a, b) => Math.round(a + (b - a) * t);
    RAMP.push(`rgb(${mix(238, 55)},${mix(240, 48)},${mix(251, 163)})`);
  }
  const heatIdx = (v, max) => (max > 0 && isFinite(v) && v >= 0 ? Math.min(10, Math.round((v / max) * 10)) : 0);

  /* ---------- 操作入口（全部记入轨迹） ---------- */
  let toastTimer = null;
  function toast(msg) {
    const el = $('#toast');
    el.textContent = msg;
    el.classList.add('show');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(() => el.classList.remove('show'), 2800);
  }
  function contextAnchorNote() {
    const nF = DIMS.reduce((s, d) => s + state.filters[d.id].length, 0);
    const nP = state.pinned.length;
    return `已保留 ${nF} 项过滤 · ${nP} 处锚定 · 度量「${measureById[state.measure].name}」 · 排序${state.sortDir === 'desc' ? '降序' : '升序'}`;
  }

  function toggleFilter(dimId, nodeId, label) {
    const arr = state.filters[dimId];
    const adding = !arr.includes(nodeId);
    if (adding) arr.push(nodeId); else arr.splice(arr.indexOf(nodeId), 1);
    pushOp(`${adding ? '过滤＋' : '过滤－'} ${dimById[dimId].name}·${label}`,
      { source: '维度轨道', detail: `${dimById[dimId].name}面板勾选` });
    render();
  }
  function clearFilters() {
    DIMS.forEach((d) => { state.filters[d.id] = []; });
    pushOp('清除全部过滤', { source: '状态归属栏', detail: '一键清空' });
    render();
  }
  function setAxis(axis, dimId, via) {
    if (axis === 'row') {
      if (state.rowDim === dimId) return;
      if (state.colDim === dimId) { // 交换行列
        state.colDim = state.rowDim; state.rowDim = dimId;
        pushOp(`换轴 · 行/列交换为 ${dimById[dimId].name}`, { source: via, detail: '目标维度已在另一轴，执行交换' });
      } else {
        state.rowDim = dimId;
        pushOp(`换轴 · 行维度 → ${dimById[dimId].name}`, { source: via, detail: '投影重排' });
      }
    } else {
      if (state.colDim === dimId) return;
      if (state.rowDim === dimId) {
        state.rowDim = state.colDim; state.colDim = dimId;
        pushOp(`换轴 · 行/列交换为 ${dimById[dimId].name}`, { source: via, detail: '目标维度已在另一轴，执行交换' });
      } else {
        state.colDim = dimId;
        pushOp(`换轴 · 列维度 → ${dimById[dimId].name}`, { source: via, detail: '投影重排' });
      }
    }
    render();
    toast('维度已切换 · ' + contextAnchorNote()); // 认知锚回显：换轴不重置
  }
  function toggleExpand(dimId, nodeId) { // viewport 态，不入轨迹
    const arr = state.expanded[dimId];
    const i = arr.indexOf(nodeId);
    if (i >= 0) arr.splice(i, 1); else arr.push(nodeId);
    render();
  }
  function togglePin(ref) {
    const key = (p) => p.rowDim + '|' + p.rowPath + '|' + p.colDim + '|' + p.colValue;
    const i = state.pinned.findIndex((p) => key(p) === key(ref));
    const adding = i < 0;
    if (adding) state.pinned.push(ref); else state.pinned.splice(i, 1);
    pushOp(`${adding ? '锚定＋' : '锚定－'} ${ref.rowLabel} × ${ref.colValue}`,
      { source: '投影区', detail: '单元格点击' });
    render();
  }
  function setMeasure(id) {
    if (state.measure === id) return;
    state.measure = id;
    pushOp(`度量 → ${measureById[id].name}`, { source: '顶栏', detail: '度量选择器' });
    render();
  }
  function toggleSort() {
    state.sortDir = state.sortDir === 'desc' ? 'asc' : 'desc';
    pushOp(`排序 → ${state.sortDir === 'desc' ? '降序' : '升序'}`, { source: '顶栏', detail: '排序切换' });
    render();
  }
  function unpinChip(i) {
    const p = state.pinned[i];
    state.pinned.splice(i, 1);
    pushOp(`锚定－ ${p.rowLabel} × ${p.colValue}`, { source: '状态归属栏', detail: 'chip 移除' });
    render();
  }

  /* ---------- 渲染 ---------- */
  function el(tag, cls, html) {
    const e = document.createElement(tag);
    if (cls) e.className = cls;
    if (html != null) e.innerHTML = html;
    return e;
  }
  const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

  function renderRail(filtered, inFiltered) {
    const root = $('#dimRail');
    root.innerHTML = '';
    DIMS.forEach((d) => {
      const sec = el('section', 'dim-block');
      const totalAgg = aggregate(filtered, state.measure);
      const isRow = state.rowDim === d.id, isCol = state.colDim === d.id;
      const head = el('div', 'dim-head');
      head.innerHTML =
        `<span class="dim-name">${esc(d.name)}</span>` +
        `<span class="dim-levels">${d.levels.join('›')}</span>` +
        `<span class="axis-badges">${isRow ? '<b class="ax ax-r">行</b>' : ''}${isCol ? '<b class="ax ax-c">列</b>' : ''}</span>`;
      const btns = el('div', 'dim-actions');
      const bR = el('button', 'mini-btn' + (isRow ? ' on' : ''), '行轴');
      bR.title = '设为行维度（保留过滤/锚定/度量）';
      bR.onclick = () => setAxis('row', d.id, '维度轨道');
      const bC = el('button', 'mini-btn' + (isCol ? ' on' : ''), '列轴');
      bC.title = '设为列维度（保留过滤/锚定/度量）';
      bC.onclick = () => setAxis('col', d.id, '维度轨道');
      btns.append(bR, bC);
      head.appendChild(btns);
      sec.appendChild(head);

      const list = el('div', 'dim-values');
      (function walk(node, depth) {
        node.children.forEach((c) => {
          const checked = state.filters[d.id].includes(c.id);
          const expanded = state.expanded[d.id].includes(c.id);
          const agg = aggregate(c.rec.filter((i) => inFiltered.has(i)), state.measure);
          const pct = totalAgg > 0 ? Math.min(100, (agg / totalAgg) * 100) : 0;
          const row = el('div', 'val-row' + (checked ? ' checked' : ''));
          row.style.paddingLeft = (8 + depth * 14) + 'px';
          const caret = c.children.length
            ? `<button class="caret" data-dim="${d.id}" data-id="${esc(c.id)}" aria-label="展开/收起">${expanded ? '▾' : '▸'}</button>`
            : '<span class="caret none"></span>';
          row.innerHTML =
            caret +
            `<label class="val-label"><input type="checkbox" data-dim="${d.id}" data-id="${esc(c.id)}" ${checked ? 'checked' : ''}>` +
            `<span class="val-name">${esc(c.label)}</span></label>` +
            `<span class="val-share"><i style="width:${pct.toFixed(1)}%"></i></span>`;
          list.appendChild(row);
          if (expanded) walk(c, depth + 1);
        });
      })(TREES[d.id], 0);
      sec.appendChild(list);
      root.appendChild(sec);
    });
  }

  function renderAttribution(filteredCount) {
    const bar = $('#attrBar');
    bar.innerHTML = '';
    const left = el('div', 'attr-left');
    left.innerHTML = '<span class="attr-title">状态归属</span>';
    let nF = 0;
    DIMS.forEach((d) => state.filters[d.id].forEach((id) => {
      nF++;
      const node = findNode(d.id, id);
      const chip = el('span', 'chip chip-filter',
        `<em class="chip-dim">${esc(d.name)}</em>${esc(node.label)}` +
        `<i class="origin" title="来源归属：维度轨道面板勾选">维度轨道</i>` +
        `<button class="chip-x" data-kind="filter" data-dim="${d.id}" data-id="${esc(id)}" aria-label="移除过滤">×</button>`);
      left.appendChild(chip);
    }));
    state.pinned.forEach((p, i) => {
      const dangling = p.rowDim !== state.rowDim || p.colDim !== state.colDim;
      const chip = el('span', 'chip chip-pin' + (dangling ? ' dangling' : ''),
        `★ ${esc(p.rowLabel)}×${esc(p.colValue)}` +
        `<span class="pin-val">${fmtMeasure(p.measure, p.value)}</span>` +
        (dangling ? '<i class="origin warn" title="锚定所在投影已被切换，切回后自动复显">悬空</i>'
                  : '<i class="origin">投影区</i>') +
        `<button class="chip-x" data-kind="pin" data-i="${i}" aria-label="移除锚定">×</button>`);
      left.appendChild(chip);
    });
    if (!nF && !state.pinned.length) {
      left.appendChild(el('span', 'attr-empty', '无过滤 · 无锚定（即初始状态）'));
    }
    const right = el('div', 'attr-right');
    right.innerHTML = `<span class="rec-count">记录 <b>${fmtInt(filteredCount)}</b> / ${fmtInt(ROWS.length)}</span>`;
    if (nF || state.pinned.length) {
      const clear = el('button', 'mini-btn', '清除全部');
      clear.onclick = clearFilters;
      right.appendChild(clear);
    }
    bar.append(left, right);
  }

  function renderGrid(filtered) {
    const wrap = $('#gridWrap');
    wrap.innerHTML = '';
    if (!filtered.length) { // 空态（state_completeness）
      const empty = el('div', 'empty-panel');
      empty.innerHTML = '<h3>当前过滤组合下没有记录</h3><p>过滤器把记录集缩小到了 0 条 —— 认知上下文仍在，可清除过滤或回滚轨迹。</p>';
      const b = el('button', 'btn primary', '清除全部过滤');
      b.onclick = clearFilters;
      empty.appendChild(b);
      wrap.appendChild(empty);
      return;
    }
    const rowDimId = state.rowDim, colDimId = state.colDim;
    const m = state.measure;
    const colNodes = TREES[colDimId].children;

    // 列过滤索引
    const colRecs = colNodes.map((c) => {
      const set = new Set();
      c.rec.forEach((i) => set.add(i));
      return set;
    });
    const inFiltered = new Set(filtered);
    const aggOf = (node) => aggregate(node.rec.filter((i) => inFiltered.has(i)), m);

    // 排序：仅对顶层行生效（children 保持层级自然序，不打散树形分组）
    let topOrder = null;
    if (state.sortDir !== 'none') {
      const aggById = new Map(TREES[rowDimId].children.map((c) => [c.id, aggOf(c)]));
      const sorted = [...TREES[rowDimId].children].sort((a, b) =>
        state.sortDir === 'desc' ? aggById.get(b.id) - aggById.get(a.id)
                                 : aggById.get(a.id) - aggById.get(b.id));
      const order = new Map(sorted.map((n, i) => [n.id, i]));
      topOrder = (kids) => [...kids].sort((a, b) => (order.get(a.id) ?? 0) - (order.get(b.id) ?? 0));
    }
    const rowItems = flattenRows(rowDimId, topOrder);
    rowItems.forEach((ri) => { ri.agg = aggOf(ri.node); });

    // 热力归一化：以当前矩阵最大值为 1
    let max = 0;
    rowItems.forEach((ri) => {
      ri.cells = colNodes.map((cn, ci) => {
        const idxs = ri.node.rec.filter((i) => inFiltered.has(i) && colRecs[ci].has(i));
        return { v: aggregate(idxs, m), n: idxs.length };
      });
      ri.cells.forEach((c) => { if (isFinite(c.v)) max = Math.max(max, c.v); });
    });

    // 锚定命中检测（跨换轴持久：同轴同路径才高亮，否则在归属栏显示“悬空”）
    const pinHits = new Set();
    state.pinned.forEach((p) => {
      if (p.rowDim === rowDimId && p.colDim === colDimId) pinHits.add(p.rowPath + '|' + p.colValue);
    });

    const title = `行[${dimById[rowDimId].name}] × 列[${dimById[colDimId].name}] · ${measureById[m].name}`;
    $('#gridTitle').textContent = '投影 ' + title;
    $('#ctxAnchor').textContent = contextAnchorNote();

    const table = el('table', 'xgrid');
    const thead = el('thead');
    const hr = el('tr');
    hr.innerHTML = `<th class="rh corner">${esc(dimById[rowDimId].name)} \\ ${esc(dimById[colDimId].name)}</th>`;
    colNodes.forEach((cn, ci) => {
      const tot = colRecs[ci].size ? filtered.filter((i) => colRecs[ci].has(i)).length : 0;
      const share = filtered.length ? (tot / filtered.length * 100) : 0;
      hr.innerHTML += `<th class="ch"><span>${esc(cn.label)}</span><i>${share.toFixed(0)}%</i></th>`;
    });
    hr.innerHTML += '<th class="ch total">合计</th>';
    thead.appendChild(hr);
    table.appendChild(thead);

    const tbody = el('tbody');
    rowItems.forEach((ri) => {
      const tr = el('tr');
      const hasKids = ri.node.children.length > 0;
      const expanded = state.expanded[rowDimId].includes(ri.node.id);
      const rh = el('th', 'rh');
      rh.style.paddingLeft = (10 + ri.depth * 16) + 'px';
      rh.innerHTML =
        (hasKids ? `<button class="caret" data-dim="${rowDimId}" data-id="${esc(ri.node.id)}" aria-label="下钻/上卷">${expanded ? '▾' : '▸'}</button>` : '<span class="caret none"></span>') +
        `<span class="rh-name">${esc(ri.node.label)}</span>` +
        `<span class="rh-agg">${fmtMeasure(m, ri.agg)}</span>`;
      tr.appendChild(rh);
      ri.cells.forEach((c, ci) => {
        const td = el('td', 'cell');
        const idx = heatIdx(c.v, max);
        td.style.background = RAMP[idx];
        if (idx >= 7) td.classList.add('dark');
        const key = ri.node.id + '|' + colNodes[ci].label;
        if (pinHits.has(key)) td.classList.add('pinned');
        if (!c.n) td.classList.add('void');
        td.dataset.rowPath = ri.node.id;
        td.dataset.rowLabel = ri.node.label;
        td.dataset.rowDepth = ri.depth;
        td.dataset.colIdx = ci;
        td.dataset.colValue = colNodes[ci].label;
        td.dataset.value = c.v;
        td.dataset.count = c.n;
        td.innerHTML = c.n
          ? `<span class="cell-v">${fmtMeasure(m, c.v)}</span>` + (pinHits.has(key) ? '<b class="pin-star">★</b>' : '')
          : '<span class="cell-void">—</span>';
        tr.appendChild(td);
      });
      const tot = el('td', 'cell total', `<span class="cell-v">${fmtMeasure(m, ri.agg)}</span>`);
      tot.style.background = RAMP[heatIdx(ri.agg, max)];
      if (heatIdx(ri.agg, max) >= 7) tot.classList.add('dark');
      tr.appendChild(tot);
      tbody.appendChild(tr);
    });
    table.appendChild(tbody);
    const scroller = el('div', 'grid-scroller');
    scroller.appendChild(table);
    wrap.appendChild(scroller);
  }

  function renderTrail() {
    const t = $('#trail');
    t.innerHTML = '<span class="trail-title">状态轨迹</span>';
    const strip = el('div', 'trail-strip');
    trail.forEach((e, i) => {
      const past = i <= ptr;
      const c = el('button', 'trail-item' + (i === ptr ? ' current' : past ? ' past' : ' future'));
      const tm = new Date(e.ts);
      c.innerHTML = `<b>${i + 1}</b> ${esc(e.label)}<i class="origin">${esc(e.origin.source)}</i>` +
        `<time>${String(tm.getMinutes()).padStart(2, '0')}:${String(tm.getSeconds()).padStart(2, '0')}</time>`;
      c.title = `回滚到「${e.label}」\n来源：${e.origin.source}${e.origin.detail ? ' · ' + e.origin.detail : ''}`;
      c.onclick = () => { jumpTo(i); toast(`已回滚到第 ${i + 1} 步「${e.label}」`); };
      strip.appendChild(c);
    });
    t.appendChild(strip);
  }

  function renderTopbar(filtered) {
    $('#measureSel').value = state.measure;
    $('#sortBtn').textContent = state.sortDir === 'desc' ? '排序↓' : '排序↑';
    $('#undoBtn').disabled = ptr <= 0;
    $('#redoBtn').disabled = ptr >= trail.length - 1;
    $('#recMain').textContent = `记录 ${fmtInt(filtered.length)} / ${fmtInt(ROWS.length)}`;
  }

  function render(opts) {
    try {
      const filtered = computeFiltered();
      renderRail(filtered, new Set(filtered));
      renderAttribution(filtered.length);
      renderGrid(filtered);
      renderTrail();
      renderTopbar(filtered);
      $('#fatal').hidden = true;
      if (opts && opts.jumped) { /* 回滚渲染，不追加轨迹 */ }
    } catch (err) { // error 态（state_completeness）
      console.error(err);
      $('#fatalMsg').textContent = String(err && err.message || err);
      $('#fatal').hidden = false;
    }
  }

  /* ---------- 单元格悬浮预览（cell-inspector，contextual） ---------- */
  const tip = $('#cellTip');
  $('#gridWrap').addEventListener('mousemove', (e) => {
    const td = e.target.closest('td.cell');
    if (!td || td.classList.contains('total')) { tip.classList.remove('show'); return; }
    const m = state.measure;
    tip.innerHTML =
      `<b>${esc(td.dataset.rowLabel)}</b> × <b>${esc(td.dataset.colValue)}</b><br>` +
      `${measureById[m].name}：<b>${fmtMeasure(m, +td.dataset.value)}</b><br>` +
      `记录数：${fmtInt(+td.dataset.count)} · 全集占比 ${(td.dataset.count / ROWS.length * 100).toFixed(1)}%<br>` +
      '<i>点击锚定 / 再次点击取消（换轴后保留）</i>';
    tip.classList.add('show');
    const wrapRect = $('#gridWrap').getBoundingClientRect();
    tip.style.left = Math.min(e.clientX - wrapRect.left + 14, wrapRect.width - 240) + 'px';
    tip.style.top = (e.clientY - wrapRect.top + 14) + 'px';
  });
  $('#gridWrap').addEventListener('mouseleave', () => tip.classList.remove('show'));

  /* ---------- 事件绑定 ---------- */
  document.addEventListener('click', (e) => {
    const caret = e.target.closest('button.caret');
    if (caret) { toggleExpand(caret.dataset.dim, caret.dataset.id); return; }
    const chipX = e.target.closest('.chip-x');
    if (chipX) {
      if (chipX.dataset.kind === 'filter') {
        const dimId = chipX.dataset.dim, id = chipX.dataset.id;
        state.filters[dimId].splice(state.filters[dimId].indexOf(id), 1);
        pushOp(`过滤－ ${dimById[dimId].name}·${findNode(dimId, id).label}`,
          { source: '状态归属栏', detail: 'chip 单独移除' });
        render();
      } else unpinChip(+chipX.dataset.i);
      return;
    }
    const cell = e.target.closest('td.cell:not(.total)');
    if (cell && cell.dataset.count !== '0') {
      togglePin({
        rowDim: state.rowDim, colDim: state.colDim,
        rowPath: cell.dataset.rowPath, rowLabel: cell.dataset.rowLabel,
        colValue: cell.dataset.colValue, measure: state.measure,
        value: +cell.dataset.value
      });
    }
  });
  document.addEventListener('change', (e) => {
    const cb = e.target.closest('input[type="checkbox"][data-dim]');
    if (cb) {
      const label = findNode(cb.dataset.dim, cb.dataset.id).label;
      toggleFilter(cb.dataset.dim, cb.dataset.id, label);
    }
  });
  $('#rowSel').addEventListener('change', (e) => setAxis('row', e.target.value, '投影区'));
  $('#colSel').addEventListener('change', (e) => setAxis('col', e.target.value, '投影区'));
  $('#measureSel').addEventListener('change', (e) => setMeasure(e.target.value));
  $('#sortBtn').addEventListener('click', toggleSort);
  $('#undoBtn').addEventListener('click', undo);
  $('#redoBtn').addEventListener('click', redo);
  $('#resetBtn').addEventListener('click', resetAll);
  document.addEventListener('keydown', (e) => { // 键盘契约：撤销 / 重做
    if (!(e.ctrlKey || e.metaKey)) return;
    const k = e.key.toLowerCase();
    if (k === 'z' && !e.shiftKey) { e.preventDefault(); undo(); }
    else if ((k === 'z' && e.shiftKey) || k === 'y') { e.preventDefault(); redo(); }
  });

  /* ---------- 轴选择器 / 度量选择器选项 ---------- */
  function fillAxisSelects() {
    const opts = DIMS.map((d) => `<option value="${d.id}">${d.name}</option>`).join('');
    $('#rowSel').innerHTML = opts; $('#colSel').innerHTML = opts;
    $('#measureSel').innerHTML = MEASURES.map((mm) => `<option value="${mm.id}">${mm.name}</option>`).join('');
  }

  /* ---------- 启动：数据内联就绪，首帧即完整应用（无加载态） ---------- */
  fillAxisSelects();
  pushOp('初始状态', { source: '系统', detail: CUBE.meta.generatedBy });
  ptr = 0;
  render();
})();

content.content:
1	/* 多维棱镜 · 应用核心
2	 * 状态模型（SDIR state_ownership）：
3	 *   query     = filters + axes + measure（每次变更加入带归属的轨迹，可回滚）
4	 *   selection = pinned 锚定集合（跨换轴持久）
5	 *   viewport  = expanded 展开态 / 滚动（不进轨迹）
6	 *   mode      = sortDir（顶栏持有，同样入轨迹）
7	 * 成功标准：换轴动作白名单化 —— 只触碰 rowDim/colDim，其余全部保留。
8	 */
9	(function () {
10	  'use strict';
11	  const CUBE = window.CUBE;
12	  const DIMS = CUBE.dims, TREES = CUBE.trees, ROWS = CUBE.rows, MEASURES = CUBE.measures;
13	  const $ = (sel) => document.querySelector(sel);
14	  const dimById = Object.fromEntries(DIMS.map((d) => [d.id, d]));
15	  const measureById = Object.fromEntries(MEASURES.map((m) => [m.id, m]));
16	
17	  /* ---------- 格式化 ---------- */
18	  const fmtMoney = (v) => {
19	    const a = Math.abs(v);
20	    if (a >= 1e8) return '¥' + (v / 1e8).toFixed(2) + '亿';
21	    if (a >= 1e4) return '¥' + (v / 1e4).toFixed(1) + '万';
22	    return '¥' + Math.round(v);
23	  };
24	  const fmtInt = (v) => Math.round(v).toLocaleString('zh-CN');
25	  const fmtPct = (v) => (v * 100).toFixed(1) + '%';
26	  function fmtMeasure(id, v) {
27	    const f = measureById[id].fmt;
28	    return f === 'money' ? fmtMoney(v) : f === 'int' ? fmtInt(v) : fmtPct(v);
29	  }
30	
31	  /* ---------- 初始状态 ---------- */
32	  function initialState() {
33	    const filters = {}, expanded = {};
34	    DIMS.forEach((d) => { filters[d.id] = []; expanded[d.id] = []; });
35	    expanded.category = ['手机通讯']; // 初始示范层级展开（viewport 态）
36	    return {
37	      filters,
38	      rowDim: 'category', colDim: 'quarter',
39	      measure: 'revenue', sortDir: 'desc',
40	      pinned: [], expanded
41	    };
42	  }
43	  let state = initialState();
44	
45	  /* ---------- 状态轨迹（归属 + 回退） ---------- */
46	  const TRAIL_MAX = 50;
47	  let trail = [], ptr = -1;
48	  const clone = (s) => JSON.parse(JSON.stringify(s));
49	  function pushOp(label, origin) {
50	    // 轨迹记录：动作 + 来源归属 + 快照。未来分支（回滚后产生新操作）按撤销语义截断。
51	    // 首条「初始状态」永不移除：重置动作以它为基准。
52	    trail = trail.slice(0, ptr + 1);
53	    trail.push({ label, origin, ts: new Date(), snap: clone(state) });
54	    if (trail.length > TRAIL_MAX) trail.splice(1, 1);
55	    ptr = trail.length - 1;
56	  }
57	  function jumpTo(i) {
58	    if (i < 0 || i >= trail.length) return;
59	    ptr = i;
60	    state = clone(trail[i].snap);
61	    render({ jumped: true });
62	  }
63	  const undo = () => jumpTo(ptr - 1);
64	  const redo = () => jumpTo(ptr + 1);
65	  function resetAll() {
66	    state = clone(trail[0].snap);
67	    pushOp('重置全部状态', { source: '顶栏', detail: '恢复初始快照' });
68	    render();
69	    toast('已重置全部状态（可在轨迹中回退到重置前）');
70	  }
71	
72	  /* ---------- 过滤语义：同维度值之间 OR，跨维度 AND ---------- */
73	  function findNode(dimId, id) {
74	    let found = null;
75	    (function walk(n) {
76	      if (n.id === id) { found = n; return; }
77	      n.children.forEach(walk);
78	    })(TREES[dimId]);
79	    return found;
80	  }
81	  function computeFiltered() {
82	    const allow = {};
83	    for (const d of DIMS) {
84	      const checked = state.filters[d.id];
85	      if (!checked.length) continue;
86	      const set = new Set();
87	      checked.forEach((id) => {
88	        const n = findNode(d.id, id);
89	        (function collect(x) {
90	          if (!x.children.length) set.add(x.id);
91	          x.children.forEach(collect);
92	        })(n);
93	      });
94	      allow[d.id] = set;
95	    }
96	    const idxs = [];
97	    outer: for (let i = 0; i < ROWS.length; i++) {
98	      const r = ROWS[i];
99	      for (const d in allow) if (!allow[d].has(r[d])) continue outer;
100	      idxs.push(i);
101	    }
102	    return idxs;
103	  }
104	  function aggregate(idxs, measureId) {
105	    let revenue = 0, profit = 0, orders = 0, returns = 0;
106	    for (const i of idxs) {
107	      const r = ROWS[i];
108	      revenue += r.revenue; profit += r.profit; orders += r.orders; returns += r.returns;
109	    }
110	    if (measureId === 'revenue') return revenue;
111	    if (measureId === 'profit') return profit;
112	    if (measureId === 'orders') return orders;
113	    return orders ? returns / orders : NaN; // returnRate
114	  }
115	
116	  /* ---------- 行树扁平化（viewport：展开态记忆在各维度名下，跨换轴保留） ----------
117	   * topOrder 仅对顶层行生效（排序），子孙保持层级自然序，不打散树形分组。 */
118	  function flattenRows(dimId, topOrder) {
119	    const out = [];
120	    (function walk(node, depth) {
121	      const kids = depth === 0 && topOrder ? topOrder(node.children) : node.children;
122	      kids.forEach((c) => {
123	        out.push({ node: c, depth });
124	        if (state.expanded[dimId].includes(c.id)) walk(c, depth + 1);
125	      });
126	    })(TREES[dimId], 0);
127	    return out;
128	  }
129	
130	  /* ---------- 热力梯度（靛蓝单色，11 档；≥7 档白字保 AA 对比） ---------- */
131	  const RAMP = [];
132	  for (let i = 0; i <= 10; i++) {
133	    const t = i / 10;
134	    const mix = (a, b) => Math.round(a + (b - a) * t);
135	    RAMP.push(`rgb(${mix(238, 55)},${mix(240, 48)},${mix(251, 163)})`);
136	  }
137	  const heatIdx = (v, max) => (max > 0 && isFinite(v) && v >= 0 ? Math.min(10, Math.round((v / max) * 10)) : 0);
138	
139	  /* ---------- 操作入口（全部记入轨迹） ---------- */
140	  let toastTimer = null;
141	  function toast(msg) {
142	    const el = $('#toast');
143	    el.textContent = msg;
144	    el.classList.add('show');
145	    clearTimeout(toastTimer);
146	    toastTimer = setTimeout(() => el.classList.remove('show'), 2800);
147	  }
148	  function contextAnchorNote() {
149	    const nF = DIMS.reduce((s, d) => s + state.filters[d.id].length, 0);
150	    const nP = state.pinned.length;
151	    return `已保留 ${nF} 项过滤 · ${nP} 处锚定 · 度量「${measureById[state.measure].name}」 · 排序${state.sortDir === 'desc' ? '降序' : '升序'}`;
152	  }
153	
154	  function toggleFilter(dimId, nodeId, label) {
155	    const arr = state.filters[dimId];
156	    const adding = !arr.includes(nodeId);
157	    if (adding) arr.push(nodeId); else arr.splice(arr.indexOf(nodeId), 1);
158	    pushOp(`${adding ? '过滤＋' : '过滤－'} ${dimById[dimId].name}·${label}`,
159	      { source: '维度轨道', detail: `${dimById[dimId].name}面板勾选` });
160	    render();
161	  }
162	  function clearFilters() {
163	    DIMS.forEach((d) => { state.filters[d.id] = []; });
164	    pushOp('清除全部过滤', { source: '状态归属栏', detail: '一键清空' });
165	    render();
166	  }
167	  function setAxis(axis, dimId, via) {
168	    if (axis === 'row') {
169	      if (state.rowDim === dimId) return;
170	      if (state.colDim === dimId) { // 交换行列
171	        state.colDim = state.rowDim; state.rowDim = dimId;
172	        pushOp(`换轴 · 行/列交换为 ${dimById[dimId].name}`, { source: via, detail: '目标维度已在另一轴，执行交换' });
173	      } else {
174	        state.rowDim = dimId;
175	        pushOp(`换轴 · 行维度 → ${dimById[dimId].name}`, { source: via, detail: '投影重排' });
176	      }
177	    } else {
178	      if (state.colDim === dimId) return;
179	      if (state.rowDim === dimId) {
180	        state.rowDim = state.colDim; state.colDim = dimId;
181	        pushOp(`换轴 · 行/列交换为 ${dimById[dimId].name}`, { source: via, detail: '目标维度已在另一轴，执行交换' });
182	      } else {
183	        state.colDim = dimId;
184	        pushOp(`换轴 · 列维度 → ${dimById[dimId].name}`, { source: via, detail: '投影重排' });
185	      }
186	    }
187	    render();
188	    toast('维度已切换 · ' + contextAnchorNote()); // 认知锚回显：换轴不重置
189	  }
190	  function toggleExpand(dimId, nodeId) { // viewport 态，不入轨迹
191	    const arr = state.expanded[dimId];
192	    const i = arr.indexOf(nodeId);
193	    if (i >= 0) arr.splice(i, 1); else arr.push(nodeId);
194	    render();
195	  }
196	  function togglePin(ref) {
197	    const key = (p) => p.rowDim + '|' + p.rowPath + '|' + p.colDim + '|' + p.colValue;
198	    const i = state.pinned.findIndex((p) => key(p) === key(ref));
199	    const adding = i < 0;
200	    if (adding) state.pinned.push(ref); else state.pinned.splice(i, 1);
201	    pushOp(`${adding ? '锚定＋' : '锚定－'} ${ref.rowLabel} × ${ref.colValue}`,
202	      { source: '投影区', detail: '单元格点击' });
203	    render();
204	  }
205	  function setMeasure(id) {
206	    if (state.measure === id) return;
207	    state.measure = id;
208	    pushOp(`度量 → ${measureById[id].name}`, { source: '顶栏', detail: '度量选择器' });
209	    render();
210	  }
211	  function toggleSort() {
212	    state.sortDir = state.sortDir === 'desc' ? 'asc' : 'desc';
213	    pushOp(`排序 → ${state.sortDir === 'desc' ? '降序' : '升序'}`, { source: '顶栏', detail: '排序切换' });
214	    render();
215	  }
216	  function unpinChip(i) {
217	    const p = state.pinned[i];
218	    state.pinned.splice(i, 1);
219	    pushOp(`锚定－ ${p.rowLabel} × ${p.colValue}`, { source: '状态归属栏', detail: 'chip 移除' });
220	    render();
221	  }
222	
223	  /* ---------- 渲染 ---------- */
224	  function el(tag, cls, html) {
225	    const e = document.createElement(tag);
226	    if (cls) e.className = cls;
227	    if (html != null) e.innerHTML = html;
228	    return e;
229	  }
230	  const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
231	
232	  function renderRail(filtered, inFiltered) {
233	    const root = $('#dimRail');
234	    root.innerHTML = '';
235	    DIMS.forEach((d) => {
236	      const sec = el('section', 'dim-block');
237	      const totalAgg = aggregate(filtered, state.measure);
238	      const isRow = state.rowDim === d.id, isCol = state.colDim === d.id;
239	      const head = el('div', 'dim-head');
240	      head.innerHTML =
241	        `<span class="dim-name">${esc(d.name)}</span>` +
242	        `<span class="dim-levels">${d.levels.join('›')}</span>` +
243	        `<span class="axis-badges">${isRow ? '<b class="ax ax-r">行</b>' : ''}${isCol ? '<b class="ax ax-c">列</b>' : ''}</span>`;
244	      const btns = el('div', 'dim-actions');
245	      const bR = el('button', 'mini-btn' + (isRow ? ' on' : ''), '行轴');
246	      bR.title = '设为行维度（保留过滤/锚定/度量）';
247	      bR.onclick = () => setAxis('row', d.id, '维度轨道');
248	      const bC = el('button', 'mini-btn' + (isCol ? ' on' : ''), '列轴');
249	      bC.title = '设为列维度（保留过滤/锚定/度量）';
250	      bC.onclick = () => setAxis('col', d.id, '维度轨道');
251	      btns.append(bR, bC);
252	      head.appendChild(btns);
253	      sec.appendChild(head);
254	
255	      const list = el('div', 'dim-values');
256	      (function walk(node, depth) {
257	        node.children.forEach((c) => {
258	          const checked = state.filters[d.id].includes(c.id);
259	          const expanded = state.expanded[d.id].includes(c.id);
260	          const agg = aggregate(c.rec.filter((i) => inFiltered.has(i)), state.measure);
261	          const pct = totalAgg > 0 ? Math.min(100, (agg / totalAgg) * 100) : 0;
262	          const row = el('div', 'val-row' + (checked ? ' checked' : ''));
263	          row.style.paddingLeft = (8 + depth * 14) + 'px';
264	          const caret = c.children.length
265	            ? `<button class="caret" data-dim="${d.id}" data-id="${esc(c.id)}" aria-label="展开/收起">${expanded ? '▾' : '▸'}</button>`
266	            : '<span class="caret none"></span>';
267	          row.innerHTML =
268	            caret +
269	            `<label class="val-label"><input type="checkbox" data-dim="${d.id}" data-id="${esc(c.id)}" ${checked ? 'checked' : ''}>` +
270	            `<span class="val-name">${esc(c.label)}</span></label>` +
271	            `<span class="val-share"><i style="width:${pct.toFixed(1)}%"></i></span>`;
272	          list.appendChild(row);
273	          if (expanded) walk(c, depth + 1);
274	        });
275	      })(TREES[d.id], 0);
276	      sec.appendChild(list);
277	      root.appendChild(sec);
278	    });
279	  }
280	
281	  function renderAttribution(filteredCount) {
282	    const bar = $('#attrBar');
283	    bar.innerHTML = '';
284	    const left = el('div', 'attr-left');
285	    left.innerHTML = '<span class="attr-title">状态归属</span>';
286	    let nF = 0;
287	    DIMS.forEach((d) => state.filters[d.id].forEach((id) => {
288	      nF++;
289	      const node = findNode(d.id, id);
290	      const chip = el('span', 'chip chip-filter',
291	        `<em class="chip-dim">${esc(d.name)}</em>${esc(node.label)}` +
292	        `<i class="origin" title="来源归属：维度轨道面板勾选">维度轨道</i>` +
293	        `<button class="chip-x" data-kind="filter" data-dim="${d.id}" data-id="${esc(id)}" aria-label="移除过滤">×</button>`);
294	      left.appendChild(chip);
295	    }));
296	    state.pinned.forEach((p, i) => {
297	      const dangling = p.rowDim !== state.rowDim || p.colDim !== state.colDim;
298	      const chip = el('span', 'chip chip-pin' + (dangling ? ' dangling' : ''),
299	        `★ ${esc(p.rowLabel)}×${esc(p.colValue)}` +
300	        `<span class="pin-val">${fmtMeasure(p.measure, p.value)}</span>` +
301	        (dangling ? '<i class="origin warn" title="锚定所在投影已被切换，切回后自动复显">悬空</i>'
302	                  : '<i class="origin">投影区</i>') +
303	        `<button class="chip-x" data-kind="pin" data-i="${i}" aria-label="移除锚定">×</button>`);
304	      left.appendChild(chip);
305	    });
306	    if (!nF && !state.pinned.length) {
307	      left.appendChild(el('span', 'attr-empty', '无过滤 · 无锚定（即初始状态）'));
308	    }
309	    const right = el('div', 'attr-right');
310	    right.innerHTML = `<span class="rec-count">记录 <b>${fmtInt(filteredCount)}</b> / ${fmtInt(ROWS.length)}</span>`;
311	    if (nF || state.pinned.length) {
312	      const clear = el('button', 'mini-btn', '清除全部');
313	      clear.onclick = clearFilters;
314	      right.appendChild(clear);
315	    }
316	    bar.append(left, right);
317	  }
318	
319	  function renderGrid(filtered) {
320	    const wrap = $('#gridWrap');
321	    wrap.innerHTML = '';
322	    if (!filtered.length) { // 空态（state_completeness）
323	      const empty = el('div', 'empty-panel');
324	      empty.innerHTML = '<h3>当前过滤组合下没有记录</h3><p>过滤器把记录集缩小到了 0 条 —— 认知上下文仍在，可清除过滤或回滚轨迹。</p>';
325	      const b = el('button', 'btn primary', '清除全部过滤');
326	      b.onclick = clearFilters;
327	      empty.appendChild(b);
328	      wrap.appendChild(empty);
329	      return;
330	    }
331	    const rowDimId = state.rowDim, colDimId = state.colDim;
332	    const m = state.measure;
333	    const colNodes = TREES[colDimId].children;
334	
335	    // 列过滤索引
336	    const colRecs = colNodes.map((c) => {
337	      const set = new Set();
338	      c.rec.forEach((i) => set.add(i));
339	      return set;
340	    });
341	    const inFiltered = new Set(filtered);
342	    const aggOf = (node) => aggregate(node.rec.filter((i) => inFiltered.has(i)), m);
343	
344	    // 排序：仅对顶层行生效（children 保持层级自然序，不打散树形分组）
345	    let topOrder = null;
346	    if (state.sortDir !== 'none') {
347	      const aggById = new Map(TREES[rowDimId].children.map((c) => [c.id, aggOf(c)]));
348	      const sorted = [...TREES[rowDimId].children].sort((a, b) =>
349	        state.sortDir === 'desc' ? aggById.get(b.id) - aggById.get(a.id)
350	                                 : aggById.get(a.id) - aggById.get(b.id));
351	      const order = new Map(sorted.map((n, i) => [n.id, i]));
352	      topOrder = (kids) => [...kids].sort((a, b) => (order.get(a.id) ?? 0) - (order.get(b.id) ?? 0));
353	    }
354	    const rowItems = flattenRows(rowDimId, topOrder);
355	    rowItems.forEach((ri) => { ri.agg = aggOf(ri.node); });
356	
357	    // 热力归一化：以当前矩阵最大值为 1
358	    let max = 0;
359	    rowItems.forEach((ri) => {
360	      ri.cells = colNodes.map((cn, ci) => {
361	        const idxs = ri.node.rec.filter((i) => inFiltered.has(i) && colRecs[ci].has(i));
362	        return { v: aggregate(idxs, m), n: idxs.length };
363	      });
364	      ri.cells.forEach((c) => { if (isFinite(c.v)) max = Math.max(max, c.v); });
365	    });
366	
367	    // 锚定命中检测（跨换轴持久：同轴同路径才高亮，否则在归属栏显示“悬空”）
368	    const pinHits = new Set();
369	    state.pinned.forEach((p) => {
370	      if (p.rowDim === rowDimId && p.colDim === colDimId) pinHits.add(p.rowPath + '|' + p.colValue);
371	    });
372	
373	    const title = `行[${dimById[rowDimId].name}] × 列[${dimById[colDimId].name}] · ${measureById[m].name}`;
374	    $('#gridTitle').textContent = '投影 ' + title;
375	    $('#ctxAnchor').textContent = contextAnchorNote();
376	
377	    const table = el('table', 'xgrid');
378	    const thead = el('thead');
379	    const hr = el('tr');
380	    hr.innerHTML = `<th class="rh corner">${esc(dimById[rowDimId].name)} \\ ${esc(dimById[colDimId].name)}</th>`;
381	    colNodes.forEach((cn, ci) => {
382	      const tot = colRecs[ci].size ? filtered.filter((i) => colRecs[ci].has(i)).length : 0;
383	      const share = filtered.length ? (tot / filtered.length * 100) : 0;
384	      hr.innerHTML += `<th class="ch"><span>${esc(cn.label)}</span><i>${share.toFixed(0)}%</i></th>`;
385	    });
386	    hr.innerHTML += '<th class="ch total">合计</th>';
387	    thead.appendChild(hr);
388	    table.appendChild(thead);
389	
390	    const tbody = el('tbody');
391	    rowItems.forEach((ri) => {
392	      const tr = el('tr');
393	      const hasKids = ri.node.children.length > 0;
394	      const expanded = state.expanded[rowDimId].includes(ri.node.id);
395	      const rh = el('th', 'rh');
396	      rh.style.paddingLeft = (10 + ri.depth * 16) + 'px';
397	      rh.innerHTML =
398	        (hasKids ? `<button class="caret" data-dim="${rowDimId}" data-id="${esc(ri.node.id)}" aria-label="下钻/上卷">${expanded ? '▾' : '▸'}</button>` : '<span class="caret none"></span>') +
399	        `<span class="rh-name">${esc(ri.node.label)}</span>` +
400	        `<span class="rh-agg">${fmtMeasure(m, ri.agg)}</span>`;
401	      tr.appendChild(rh);
402	      ri.cells.forEach((c, ci) => {
403	        const td = el('td', 'cell');
404	        const idx = heatIdx(c.v, max);
405	        td.style.background = RAMP[idx];
406	        if (idx >= 7) td.classList.add('dark');
407	        const key = ri.node.id + '|' + colNodes[ci].label;
408	        if (pinHits.has(key)) td.classList.add('pinned');
409	        if (!c.n) td.classList.add('void');
410	        td.dataset.rowPath = ri.node.id;
411	        td.dataset.rowLabel = ri.node.label;
412	        td.dataset.rowDepth = ri.depth;
413	        td.dataset.colIdx = ci;
414	        td.dataset.colValue = colNodes[ci].label;
415	        td.dataset.value = c.v;
416	        td.dataset.count = c.n;
417	        td.innerHTML = c.n
418	          ? `<span class="cell-v">${fmtMeasure(m, c.v)}</span>` + (pinHits.has(key) ? '<b class="pin-star">★</b>' : '')
419	          : '<span class="cell-void">—</span>';
420	        tr.appendChild(td);
421	      });
422	      const tot = el('td', 'cell total', `<span class="cell-v">${fmtMeasure(m, ri.agg)}</span>`);
423	      tot.style.background = RAMP[heatIdx(ri.agg, max)];
424	      if (heatIdx(ri.agg, max) >= 7) tot.classList.add('dark');
425	      tr.appendChild(tot);
426	      tbody.appendChild(tr);
427	    });
428	    table.appendChild(tbody);
429	    const scroller = el('div', 'grid-scroller');
430	    scroller.appendChild(table);
431	    wrap.appendChild(scroller);
432	  }
433	
434	  function renderTrail() {
435	    const t = $('#trail');
436	    t.innerHTML = '<span class="trail-title">状态轨迹</span>';
437	    const strip = el('div', 'trail-strip');
438	    trail.forEach((e, i) => {
439	      const past = i <= ptr;
440	      const c = el('button', 'trail-item' + (i === ptr ? ' current' : past ? ' past' : ' future'));
441	      const tm = new Date(e.ts);
442	      c.innerHTML = `<b>${i + 1}</b> ${esc(e.label)}<i class="origin">${esc(e.origin.source)}</i>` +
443	        `<time>${String(tm.getMinutes()).padStart(2, '0')}:${String(tm.getSeconds()).padStart(2, '0')}</time>`;
444	      c.title = `回滚到「${e.label}」\n来源：${e.origin.source}${e.origin.detail ? ' · ' + e.origin.detail : ''}`;
445	      c.onclick = () => { jumpTo(i); toast(`已回滚到第 ${i + 1} 步「${e.label}」`); };
446	      strip.appendChild(c);
447	    });
448	    t.appendChild(strip);
449	  }
450	
451	  function renderTopbar(filtered) {
452	    $('#measureSel').value = state.measure;
453	    $('#sortBtn').textContent = state.sortDir === 'desc' ? '排序↓' : '排序↑';
454	    $('#undoBtn').disabled = ptr <= 0;
455	    $('#redoBtn').disabled = ptr >= trail.length - 1;
456	    $('#recMain').textContent = `记录 ${fmtInt(filtered.length)} / ${fmtInt(ROWS.length)}`;
457	  }
458	
459	  function render(opts) {
460	    try {
461	      const filtered = computeFiltered();
462	      renderRail(filtered, new Set(filtered));
463	      renderAttribution(filtered.length);
464	      renderGrid(filtered);
465	      renderTrail();
466	      renderTopbar(filtered);
467	      $('#fatal').hidden = true;
468	      if (opts && opts.jumped) { /* 回滚渲染，不追加轨迹 */ }
469	    } catch (err) { // error 态（state_completeness）
470	      console.error(err);
471	      $('#fatalMsg').textContent = String(err && err.message || err);
472	      $('#fatal').hidden = false;
473	    }
474	  }
475	
476	  /* ---------- 单元格悬浮预览（cell-inspector，contextual） ---------- */
477	  const tip = $('#cellTip');
478	  $('#gridWrap').addEventListener('mousemove', (e) => {
479	    const td = e.target.closest('td.cell');
480	    if (!td || td.classList.contains('total')) { tip.classList.remove('show'); return; }
481	    const m = state.measure;
482	    const v = +td.dataset.value;
483	    tip.innerHTML =
484	      `<b>${esc(td.dataset.rowLabel)}</b> × <b>${esc(td.dataset.colValue)}</b><br>` +
485	      `${measureById[m].name}：<b>${+td.dataset.count ? fmtMeasure(m, v) : '—'}</b><br>` +
486	      `记录数：${fmtInt(+td.dataset.count)} · 全集占比 ${(td.dataset.count / ROWS.length * 100).toFixed(1)}%<br>` +
487	      '<i>点击锚定 / 再次点击取消（换轴后保留）</i>';
488	    tip.classList.add('show');
489	    const wrapRect = $('#gridWrap').getBoundingClientRect();
490	    tip.style.left = Math.min(e.clientX - wrapRect.left + 14, wrapRect.width - 240) + 'px';
491	    tip.style.top = (e.clientY - wrapRect.top + 14) + 'px';
492	  });
493	  $('#gridWrap').addEventListener('mouseleave', () => tip.classList.remove('show'));
494	
495	  /* ---------- 事件绑定 ---------- */
496	  document.addEventListener('click', (e) => {
497	    const caret = e.target.closest('button.caret');
498	    if (caret) { toggleExpand(caret.dataset.dim, caret.dataset.id); return; }
499	    const chipX = e.target.closest('.chip-x');
500	    if (chipX) {
501	      if (chipX.dataset.kind === 'filter') {
502	        const dimId = chipX.dataset.dim, id = chipX.dataset.id;
503	        state.filters[dimId].splice(state.filters[dimId].indexOf(id), 1);
504	        pushOp(`过滤－ ${dimById[dimId].name}·${findNode(dimId, id).label}`,
505	          { source: '状态归属栏', detail: 'chip 单独移除' });
506	        render();
507	      } else unpinChip(+chipX.dataset.i);
508	      return;
509	    }
510	    const cell = e.target.closest('td.cell:not(.total)');
511	    if (cell && cell.dataset.count !== '0') {
512	      togglePin({
513	        rowDim: state.rowDim, colDim: state.colDim,
514	        rowPath: cell.dataset.rowPath, rowLabel: cell.dataset.rowLabel,
515	        colValue: cell.dataset.colValue, measure: state.measure,
516	        value: +cell.dataset.value
517	      });
518	    }
519	  });
520	  document.addEventListener('change', (e) => {
521	    const cb = e.target.closest('input[type="checkbox"][data-dim]');
522	    if (cb) {
523	      const label = findNode(cb.dataset.dim, cb.dataset.id).label;
524	      toggleFilter(cb.dataset.dim, cb.dataset.id, label);
525	    }
526	  });
527	  $('#rowSel').addEventListener('change', (e) => setAxis('row', e.target.value, '投影区'));
528	  $('#colSel').addEventListener('change', (e) => setAxis('col', e.target.value, '投影区'));
529	  $('#measureSel').addEventListener('change', (e) => setMeasure(e.target.value));
530	  $('#sortBtn').addEventListener('click', toggleSort);
531	  $('#undoBtn').addEventListener('click', undo);
532	  $('#redoBtn').addEventListener('click', redo);
533	  $('#resetBtn').addEventListener('click', resetAll);
534	  document.addEventListener('keydown', (e) => { // 键盘契约：撤销 / 重做
535	    if (!(e.ctrlKey || e.metaKey)) return;
536	    const k = e.key.toLowerCase();
537	    if (k === 'z' && !e.shiftKey) { e.preventDefault(); undo(); }
538	    else if ((k === 'z' && e.shiftKey) || k === 'y') { e.preventDefault(); redo(); }
539	  });
540	
541	  /* ---------- 轴选择器 / 度量选择器选项 ---------- */
542	  function fillAxisSelects() {
543	    const opts = DIMS.map((d) => `<option value="${d.id}">${d.name}</option>`).join('');
544	    $('#rowSel').innerHTML = opts; $('#colSel').innerHTML = opts;
545	    $('#measureSel').innerHTML = MEASURES.map((mm) => `<option value="${mm.id}">${mm.name}</option>`).join('');
546	  }
547	
548	  /* ---------- 启动：数据内联就绪，首帧即完整应用（无加载态） ---------- */
549	  fillAxisSelects();
550	  pushOp('初始状态', { source: '系统', detail: CUBE.meta.generatedBy });
551	  ptr = 0;
552	  render();
553	})();
