/* 单元格悬浮预览 */
#cellTip {
  position: absolute; z-index: 10; pointer-events: none;
  max-width: 240px; padding: 8px 10px;
  background: #232936; color: #f2f4fa;
  border-radius: 8px; font-size: 12px; line-height: 1.55;
