/* 多维棱镜 · 紧凑专业工具视觉（WEB-DESKTOP / H-13 Structured Density / H-23 AA floor）
 * AA 约束：全部文字/图标对底 ≥4.5:1；可点目标 ≥24×24；禁用态用实色不用透明度。 */
:root {
  --bg: #f2f3f7;
  --panel: #ffffff;
  --border: #e3e5ec;
  --border-strong: #c9cdda;
  --text: #1c2230;
  --sub: #5c6575;      /* 对白 5.6:1，对 --bg 5.2:1 */
  --accent: #4f46e5;
  --accent-soft: #eef0fe;
  --warn: #b45309;
  --warn-soft: #fef3e2;
  --radius: 8px;
  --mono: "Consolas", "SF Mono", monospace;
}
* { box-sizing: border-box; margin: 0; padding: 0; }
html, body { height: 100%; }
body {
  font-family: system-ui, "Segoe UI", "Microsoft YaHei", "PingFang SC", sans-serif;
  font-size: 13px;
  color: var(--text);
  background: var(--bg);
  overflow: hidden;
}
button, select, input { font: inherit; color: inherit; }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; border-radius: 4px; }

#app { height: 100vh; display: flex; flex-direction: column; }

/* ---------- 顶栏 ---------- */
#topbar {
  height: 52px; flex: none;
  display: flex; align-items: center; gap: 14px;
  padding: 0 16px;
  background: var(--panel);
  border-bottom: 1px solid var(--border);
}
.brand { display: flex; align-items: baseline; gap: 8px; white-space: nowrap; }
.brand .logo { color: var(--accent); font-size: 18px; align-self: center; }
.brand b { font-size: 15px; }
.brand .sub { color: var(--sub); font-size: 12px; }
.rec-main { color: var(--sub); font-size: 12px; font-variant-numeric: tabular-nums; }
.rec-main b { color: var(--text); }
.top-actions { margin-left: auto; display: flex; align-items: center; gap: 8px; }
.sep { width: 1px; height: 20px; background: var(--border-strong); }
.btn {
  height: 28px; padding: 0 10px;
  background: var(--panel);
  border: 1px solid var(--border-strong);
  border-radius: 6px; cursor: pointer;
}
.btn:hover { background: var(--accent-soft); border-color: var(--accent); }
.btn:disabled {
  /* 实色禁用态（不用透明度，保证对比可测）：#5c6575 对 #f4f5f8 ≈ 5.2:1 */
  color: var(--sub); background: #f4f5f8; border-color: var(--border);
  cursor: default;
}
.btn.danger { color: var(--warn); }
.btn.danger:hover { background: var(--warn-soft); border-color: var(--warn); }
.axis-pick { display: inline-flex; align-items: center; gap: 6px; color: var(--sub); font-size: 12px; }
select {
  height: 28px; padding: 0 6px;
  border: 1px solid var(--border-strong); border-radius: 6px;
