.trail-item.current b, .trail-item.current .origin, .trail-item.current time { color: #e6e4ff; background: transparent; border-color: #ffffff55; }
.trail-item.future { opacity: .7; }

/* ---------- 认知锚 toast ---------- */
#toast {
  position: fixed; right: 18px; bottom: 76px; z-index: 50;
  max-width: 380px; padding: 10px 14px;
  background: #232936; color: #f2f4fa;
  border-left: 3px solid var(--accent);
  border-radius: 8px; font-size: 12.5px; line-height: 1.5;
  box-shadow: 0 8px 22px rgba(20, 24, 40, .3);
  opacity: 0; transform: translateY(8px);
  transition: opacity .18s, transform .18s;
  pointer-events: none;
}
#toast.show { opacity: 1; transform: none; }

/* 滚动条（紧凑） */
::-webkit-scrollbar { width: 10px; height: 10px; }
::-webkit-scrollbar-thumb { background: #ccd0dc; border-radius: 6px; border: 2px solid var(--bg); }
::-webkit-scrollbar-track { background: transparent; }

